COPY={}
def page(n,en,es,se,ss,ce,cs,fe,fs):
 COPY[f'DD-{n:03d}']={'en':dict(title=en[0],intro=en[1],sections=se,checklist=ce,faq=fe),'es':dict(title=es[0],intro=es[1],sections=ss,checklist=cs,faq=fs)}
page(104,('Crate sizing: measure your Doberman, then check usable space','Choose a crate by your dog’s comfortable standing, turning and resting space—not a breed-size label. Fit and learning to feel comfortable in a crate are separate questions.'),('Tamaño de jaula: mide a tu dóberman y revisa espacio útil','Elige según espacio cómodo para estar de pie, girar y descansar, no por una etiqueta de raza. Ajuste y aprender a estar cómodo son preguntas distintas.'),[
('Measure without forcing a position','Observe your dog standing naturally and resting comfortably on a nonslip surface. Record their height and the length of their resting footprint without pulling legs into place. If measuring causes concern, pause and seek help. These measurements begin the comparison; they do not prove a crate is suitable.'),('Compare internal dimensions','Ask the manufacturer for usable internal length, width and height, accounting for bedding, door openings and any divider. External dimensions and a nominal size can overstate room available to the dog. Check assembly instructions, latch security and appropriate use before bringing the crate home.'),('Check movement with choice','A suitable setup should allow comfortable standing, turning and resting. Introduce access gradually, keep the door secured open initially and observe willingness to enter and leave. Do not close a reluctant dog inside to test fit. A correct measurement does not treat separation distress or establish crate tolerance.'),('An illustrative measurement comparison','Planning example only: a resting footprint recorded as 90 × 55 cm cannot fit within a usable base of 85 × 50 cm. A larger base still needs checks for height, turning, bedding and door access. These numbers are hypothetical, not a measured Doberman, a product test or a recommended size.'),('Reassess the setup as needs change','Growing dogs and changes in bedding or mobility can alter usable space. Review comfort and fit instead of assuming a purchase remains suitable indefinitely. Seek professional advice for distress or physical discomfort; a crate should not be used to force a dog through panic.')],[
('Mide sin forzar posturas','Observa postura natural y descanso cómodo sobre suelo antideslizante. Anota altura y superficie ocupada al descansar sin estirar patas a la fuerza. Para si preocupa. Medir inicia la comparación, pero no demuestra idoneidad.'),('Compara medidas interiores','Pide longitud, anchura y altura interiores útiles, considerando cama, puerta y divisor. Medidas exteriores y talla nominal pueden exagerar espacio. Revisa montaje, cierre y uso previsto antes de comprar.'),('Comprueba movimiento voluntario','Debe permitir estar de pie, girar y descansar cómodamente. Introduce acceso gradualmente, con puerta asegurada abierta al principio. Observa entrar y salir por elección. No encierres al perro para probar ajuste; medir no resuelve angustia ni demuestra tolerancia.'),('Ejemplo ilustrativo','Solo planificación: una superficie de descanso de 90 × 55 cm no cabe en una base útil de 85 × 50 cm. Una base mayor aún requiere revisar altura, giro, cama y puerta. Son cifras hipotéticas, no perro medido, ensayo ni talla recomendada.'),('Revisa cuando cambien necesidades','Crecimiento, cama y movilidad alteran espacio. Comprueba comodidad en vez de asumir ajuste permanente. Consulta angustia o molestias; la jaula no debe obligarlo a soportar pánico.')],['Record natural standing and resting measurements.','Confirm usable internal dimensions and door access.','Account for bedding and dividers.','Check voluntary movement; keep training separate from fit.'],['Anota medidas naturales de pie y descanso.','Confirma interior útil y acceso por puerta.','Considera cama y divisores.','Comprueba movimiento voluntario; separa ajuste y aprendizaje.'],[('Does every Doberman need the same crate size?','No. Measure the individual dog and inspect usable dimensions and comfortable movement.'),('Does a larger crate fix distress?','No. Space and comfort with confinement are separate issues; distress needs appropriate support.')],[('¿Todos necesitan la misma talla?','No. Mide al perro y revisa interior útil y movimiento cómodo.'),('¿Una jaula mayor resuelve angustia?','No. Espacio y tolerancia al encierro son distintos; la angustia necesita apoyo.')])
page(105,('Choose a Doberman bed by resting space and everyday care','Compare usable sleeping space, easy access, cleaning instructions and your dog’s preferences. A marketing label cannot establish medical benefit or predict how long a bed will last.'),('Elige cama por espacio de descanso y cuidados diarios','Compara superficie útil, acceso, limpieza y preferencias. Una etiqueta comercial no demuestra beneficio médico ni predice duración.'),[
('Observe how your dog actually rests','Notice whether your dog stretches out, curls up, changes position or rests their head on an edge. Measure the occupied area gently without disturbing sleep. Raised sides reduce usable space; compare the sleeping surface rather than only the outer dimensions.'),('Compare access and stability','Check whether your dog can approach, step onto and leave the bed comfortably. Look at floor grip, edges and the room around it. Ask your veterinarian about individual mobility concerns; calling a bed orthopedic does not demonstrate treatment or pain relief.'),('Read the whole cleaning plan','Check cover removal, washing temperature, drying instructions and whether the filling can be cleaned. Confirm that the cover fits your machine and can dry before it is needed again. Consider a spare resting option while washing rather than buying on appearance alone.'),('An illustrative fit check','Planning example only: a dog’s imagined stretched resting footprint is 100 × 60 cm, while a bed’s claimed outer size is 110 × 70 cm. Thick bolsters may leave less usable room than the footprint requires. Ask for interior dimensions. This is arithmetic for comparison, not an actual product test.'),('Treat durability as evidence to collect','Inspect seams, zips, loose filling and wear during use; remove unsafe damaged bedding. Review warranty and return terms before purchase. This guide provides selection criteria and has not tested or ranked specific beds. A dog who chews bedding needs a safe management plan, not an indestructibility promise.')],[
('Observa cómo descansa','Comprueba si se estira, se acurruca, cambia postura o apoya la cabeza. Mide superficie ocupada sin interrumpir sueño. Bordes elevados reducen espacio; compara superficie para dormir, no solo exterior.'),('Compara acceso y estabilidad','Observa acercarse, subir y salir cómodamente. Revisa agarre, bordes y espacio alrededor. Consulta movilidad individual al veterinario; llamar ortopédica a una cama no demuestra tratamiento ni alivio.'),('Lee todo el plan de limpieza','Revisa retirar funda, temperatura, secado y limpieza del relleno. Confirma que cabe en la lavadora y puede secarse a tiempo. Prepara otro lugar mientras se lava.'),('Ejemplo de ajuste','Solo planificación: una superficie imaginaria de descanso de 100 × 60 cm frente a exterior anunciado de 110 × 70 cm. Bordes gruesos pueden dejar interior insuficiente. Solicita medidas útiles. Es comparación ilustrativa, no ensayo real.'),('Recoge evidencia de duración','Revisa costuras, cremalleras, relleno y desgaste; retira cama dañada peligrosa. Consulta garantía y devolución. Esta guía aporta criterios sin probar ni clasificar camas. Masticar cama requiere manejo seguro, no promesa de indestructibilidad.')],['Observe resting posture and footprint.','Ask for the usable sleeping area.','Check stable access and cleaning instructions.','Inspect wear; distinguish claims from documented evidence.'],['Observa postura y superficie ocupada.','Pide superficie útil para dormir.','Revisa acceso estable y limpieza.','Observa desgaste; distingue afirmaciones y evidencia.'],[('Does orthopedic mean proven pain relief?','No. Discuss individual care with your veterinarian and ask what evidence supports any medical claim.'),('Have you tested the beds mentioned here?','This is a criteria-based guide, not a hands-on product ranking.')],[('¿Ortopédica significa alivio demostrado?','No. Consulta cuidados individuales y pide evidencia de afirmaciones médicas.'),('¿Habéis probado las camas?','Es una guía de criterios, no una clasificación con ensayos prácticos.')])
page(107,('Leashes and long lines: choose for the setting','Match length, attachment and handling to your dog and the space around you. A long line can support managed training, but it does not guarantee control or replace recall practice.'),('Correas y líneas largas: elige según entorno','Adapta longitud, enganche y manejo al perro y espacio. Una línea larga ayuda a practicar con acceso controlado, sin garantizar control ni sustituir la llamada.'),[
('Start with where you will use it','A crowded pavement and a quiet open training area require different space management. Check local access requirements, nearby traffic and other people or animals. Select equipment appropriate to the situation rather than choosing the longest available line.'),('Check the attachment and condition','Follow the equipment manufacturer’s instructions and inspect clips, stitching and webbing. For long-line practice, seek guidance on an appropriate well-fitted harness and attachment. A harness still requires comfortable introduction and fit checks; it is not proof that any line setup is safe.'),('Learn handling before adding distractions','Use an appropriate open area, avoid wrapping the line around hands or limbs, and keep it clear of people, obstacles and other dogs. Do not let a dog accelerate to a sudden stop at the end. Ask a qualified reward-based trainer to demonstrate safe handling if you are unfamiliar with managing the slack.'),('An illustrative reach comparison','Planning example only: a five-meter line can permit access well beyond a nearby two-meter clear area. More length is not useful if the surrounding space contains hazards. The figures illustrate reach, not a tested leash or a recommended universal length. Shorten the managed range or choose another location.'),('Keep equipment separate from training progress','Practice easy recall and walking skills while supervising the environment. End if the line tangles, attachment loosens or your dog cannot remain manageable and comfortable. This guide compares use criteria without hands-on durability or strength tests. Do not treat a long line as an unattended tether.')],[
('Empieza por el lugar','Una acera concurrida y una zona abierta tranquila exigen manejo distinto. Revisa requisitos locales, tráfico y presencia de otros. No elijas simplemente la línea más larga.'),('Revisa enganche y estado','Sigue instrucciones y observa mosquetón, costuras y cinta. Para línea larga, pide orientación sobre arnés y enganche adecuados. El arnés necesita presentación y ajuste; no demuestra seguridad de cualquier combinación.'),('Aprende manejo antes de distracciones','Utiliza zona abierta apropiada, sin enrollar línea en manos o extremidades. Mantenla lejos de personas, obstáculos y perros. Evita acelerar hasta una parada brusca. Solicita demostración profesional si desconoces cómo manejar holgura.'),('Ejemplo de alcance','Solo planificación: una línea de cinco metros permite alcanzar más allá de una zona despejada de dos metros. Más longitud no ayuda si hay peligros. Cifras ilustrativas, no correa probada ni longitud universal. Reduce alcance controlado o cambia lugar.'),('Separa equipo y progreso','Practica llamada y paseo fáciles supervisando entorno. Termina ante enredos, enganche flojo o pérdida de manejo cómodo. Comparamos criterios sin ensayos de resistencia. No uses la línea como amarre sin supervisión.')],['Match length to actual safe space.','Inspect clips, stitching and attachment instructions.','Keep the line clear and avoid sudden end-of-line stops.','Practice under supervision; never use as an unattended tether.'],['Adapta longitud al espacio seguro real.','Revisa enganches, costuras e instrucciones.','Evita enredos y paradas bruscas al final.','Supervisa; no uses como amarre desatendido.'],[('Does a long line replace recall training?','No. It helps manage access while you teach skills, with supervision and safe handling.'),('Is the longest line always the best choice?','No. Choose for clear space, hazards, your handling skills and the individual dog.')],[('¿Sustituye aprender la llamada?','No. Controla acceso mientras practicas con supervisión y manejo seguro.'),('¿La más larga siempre es mejor?','No. Elige según espacio, peligros, manejo y perro.')])
for n in (104,105,107):
 for lang in ('en','es'):
  COPY[f'DD-{n:03d}'][lang]['matrix']=[('Space','Usable dimensions and surrounding clearance'),('Comfort','Voluntary movement and easy access'),('Instructions','Manufacturer use and care limits'),('Evidence','Measured specifications; no hands-on test claimed')] if lang=='en' else [('Espacio','Medidas útiles y zona despejada'),('Comodidad','Movimiento voluntario y acceso fácil'),('Instrucciones','Uso y cuidados del fabricante'),('Evidencia','Especificaciones; sin afirmar ensayo práctico')]
